local function Number(value)
    if issecretvalue and issecretvalue(value) then return false end
    if APR.IsPublicNumber then return APR:IsPublicNumber(value) end
    return type(value) == "number" and value == value and value > -math.huge and value < math.huge
end--[[APR_DIAG]]; Number = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:17:Number#2", Number)--[[/APR_DIAG]]

local function Price(value)
    return Number(value) and value >= 0
end--[[APR_DIAG]]; Price = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:23:Price#3", Price)--[[/APR_DIAG]]

local function Positive(value)
    return Number(value) and value > 0
end--[[APR_DIAG]]; Positive = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:27:Positive#4", Positive)--[[/APR_DIAG]]

local function Pair(fromID, toID)
