function taxi:IsFlightMasterCandidate(node)
    local api = self:GetAPI()
    local flags = api and api.FLAGS
    if type(flags) ~= "table" or type(node) ~= "table" or not Number(node.flags) then return true end
    -- The catalogue also includes landing-only and scripted transport points.
    local endpoint, ignored = flags.END_POINT_ONLY, flags.IGNORE_FOR_FIND_NEAREST
    return not (Positive(endpoint) and math.floor(node.flags / endpoint) % 2 == 1)
        and not (Positive(ignored) and math.floor(node.flags / ignored) % 2 == 1)
end--[[APR_DIAG]]; taxi.IsFlightMasterCandidate = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:73:taxi:IsFlightMasterCandidate#10", taxi.IsFlightMasterCandidate)--[[/APR_DIAG]]

function taxi:GetNodeName(nodeID)
    local node = self.liveNodes and self.liveNodes[nodeID]
    local name = node and node.name
    if
        type(name) == "string"
        and not (issecretvalue and issecretvalue(name))
        and name ~= ""
        and self.livePlayerID == APR.PlayerID
        and self.liveSnapshot == self:GetSnapshotKey()
    then
        return name
    end
    return self:Call("GetNodeName", nodeID)
end--[[APR_DIAG]]; taxi.GetNodeName = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:83:taxi:GetNodeName#11", taxi.GetNodeName)--[[/APR_DIAG]]

function taxi:GetSnapshotKey()
    local source = self:Call("GetSource")
    if type(source) ~= "table" then source = {} end
    local paths = type(source.paths) == "table" and source.paths or {}
    local profile = source.dataSet or source.profile or APR:GetGameVersion()
    local build, fingerprint = source.build or "unknown", paths.fingerprint or "legacy"
    if self.snapshotProfile == profile and self.snapshotBuild == build and self.snapshotFingerprint == fingerprint then
        return self.snapshotKey
    end
    self.snapshotProfile, self.snapshotBuild, self.snapshotFingerprint = profile, build, fingerprint
    self.snapshotKey = table.concat({ tostring(profile), tostring(build), tostring(fingerprint) }, ":")
    return self.snapshotKey
end--[[APR_DIAG]]; taxi.GetSnapshotKey = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:98:taxi:GetSnapshotKey#12", taxi.GetSnapshotKey)--[[/APR_DIAG]]

function taxi:GetCharacterData(snapshot)
    local character = APRData and APR.PlayerID and APRData[APR.PlayerID]
    if type(character) ~= "table" then return nil end
    if type(character.NavigationTaxi) ~= "table" then character.NavigationTaxi = {} end
    local key = snapshot or self:GetSnapshotKey()
    local data = character.NavigationTaxi[key]
    if type(data) ~= "table" then
        data = {}
        character.NavigationTaxi[key] = data
    end
    if type(data.offers) ~= "table" then data.offers = {} end
    if type(data.durations) ~= "table" then data.durations = {} end
    if not data.legacyMigrated then
        -- Former Forever observations prove a directed offer, never its fare
        -- or exact route signature. Keep that evidence without inventing either.
        if APR:GetGameVersion() == "forever" then
            for from, targets in pairs(character.TaxiRoutes or {}) do
                if type(targets) == "table" then
                    data.offers[from] = data.offers[from] or {}
                    for to, offered in pairs(targets) do
                        if offered == true and not data.offers[from][to] then
                            data.offers[from][to] = { legacy = true }
                        end
                    end
                end
            end
        end
        data.legacyMigrated = true
    end
    return data
end--[[APR_DIAG]]; taxi.GetCharacterData = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:112:taxi:GetCharacterData#13", taxi.GetCharacterData)--[[/APR_DIAG]]

local function Position(nodeID)
    local p = taxi:GetNodeWorldPosition(nodeID)
    if type(p) ~= "table" or not Number(p.instanceID) or not Number(p.x) or not Number(p.y) then return nil end
    if APR.NavigationData and APR.NavigationData.NormalizeLocation then
        local normalized = APR.NavigationData:NormalizeLocation({
            space = "world",
            instanceID = p.instanceID,
            uiMapID = p.uiMapID or p.sourceMapID,
            x = p.x,
            y = p.y,
            z = Number(p.z) and p.z or 0,
        })
        if normalized then return normalized end
    end
    return {
        x = p.x,
        y = p.y,
        z = Number(p.z) and p.z or 0,
        instanceID = p.instanceID,
        uiMapID = p.uiMapID or p.sourceMapID,
    }
end--[[APR_DIAG]]; Position = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:144:Position#14", Position)--[[/APR_DIAG]]

local function Signature(to, slots, sequence)
    if not GetNumRoutes or not TaxiGetNodeSlot or not Positive(to.slotIndex) then return nil end
    local count = GetNumRoutes(to.slotIndex)
    if not Positive(count) or count > 100 then return nil end
    local size = 1
    for index = 1, count do
        local node = slots[TaxiGetNodeSlot(to.slotIndex, index, false)]
        if not node then return nil end
        if sequence[size] ~= node then
            size = size + 1
            sequence[size] = node
        end
    end
    if sequence[size] ~= tostring(to.nodeID) then return nil end
    -- A shorter or incomplete previous route may leave a tail in this scratch
    -- buffer. Only its current prefix belongs to this itinerary.
    return table.concat(sequence, ">", 1, size)
end--[[APR_DIAG]]; Signature = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:167:Signature#15", Signature)--[[/APR_DIAG]]

function taxi:SetProbeContext(key)
    key = tostring(key or "default") .. ":" .. tostring(APR.PlayerID) .. ":" .. self:GetSnapshotKey()
    if self.probeContext ~= key then
        self.probeContext, self.probeAttempts, self.blocked = key, {}, {}
        self:InvalidateEdges()
    end
end--[[APR_DIAG]]; taxi.SetProbeContext = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:186:taxi:SetProbeContext#16", taxi.SetProbeContext)--[[/APR_DIAG]]

function taxi:MarkProbeAttempt(from, to, contextKey)
    if contextKey then self:SetProbeContext(contextKey) end
    self.probeAttempts = self.probeAttempts or {}
    self.probeAttempts[Pair(from, to)] = true
end--[[APR_DIAG]]; taxi.MarkProbeAttempt = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:194:taxi:MarkProbeAttempt#17", taxi.MarkProbeAttempt)--[[/APR_DIAG]]

function taxi:ObserveTaxiMap(nodes)
    self:InvalidateEdges()
    self.liveOffers, self.liveNodes, self.blocked = {}, {}, self.blocked or {}
    local current, bySlot = nil, {}
    for _, node in ipairs(nodes or {}) do
        if node.nodeID then self.liveNodes[node.nodeID] = node end
        if Positive(node.slotIndex) then bySlot[node.slotIndex] = node.nodeID and tostring(node.nodeID) or nil end
        if node.state == Enum.FlightPathState.Current then current = node.nodeID end
    end
    self.currentNodeID, self.liveSnapshot, self.livePlayerID = current, self:GetSnapshotKey(), APR.PlayerID
    if not current then return end
    local data = self:GetCharacterData()
    if not data then return end
    -- A complete observation replaces old offers from this origin only.
    data.offers[current] = {}
    -- Signatures share slot strings and one bounded buffer only within this
    -- observation. A new map or changed client route always rebuilds both.
    local sequence = { tostring(current) }
    for _, node in ipairs(nodes or {}) do
        if node.nodeID and node.nodeID ~= current and not node.isMapLayerTransition then
            local key = Pair(current, node.nodeID)
            if node.state == Enum.FlightPathState.Reachable and Positive(node.slotIndex) then
                local price = TaxiNodeCost and TaxiNodeCost(node.slotIndex)
                if not Price(price) then price = nil end
                local signature = Signature(node, bySlot, sequence)
                self.liveOffers[node.nodeID] = {
                    fromNodeID = current,
                    toNodeID = node.nodeID,
                    priceCopper = price,
                    signature = signature,
                    slotIndex = node.slotIndex,
                }
                data.offers[current][node.nodeID] = { priceCopper = price, signature = signature }
                self.blocked[key] = nil
            elseif node.state == Enum.FlightPathState.Unreachable then
                self.blocked[key] = true
            end
        end
    end
    if APR.navigation then
        APR.navigation:InvalidatePathCache()
        APR.navigation:RequestUpdate()
    end
end--[[APR_DIAG]]; taxi.ObserveTaxiMap = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:200:taxi:ObserveTaxiMap#18", taxi.ObserveTaxiMap)--[[/APR_DIAG]]

function taxi:CloseTaxiMap()
    if self.liveOffers then self:InvalidateEdges() end
    self.liveOffers, self.liveNodes, self.currentNodeID, self.liveSnapshot, self.livePlayerID = nil, nil, nil, nil, nil
end--[[APR_DIAG]]; taxi.CloseTaxiMap = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:245:taxi:CloseTaxiMap#19", taxi.CloseTaxiMap)--[[/APR_DIAG]]

function taxi:GetQuote(nodeID, fromID)
    if
        self.liveSnapshot ~= self:GetSnapshotKey()
        or self.livePlayerID ~= APR.PlayerID
        or (fromID and fromID ~= self.currentNodeID)
    then
        return nil
    end
    local offer, node = self.liveOffers and self.liveOffers[nodeID], self.liveNodes and self.liveNodes[nodeID]
    if
        not offer
        or not node
        or node.state ~= Enum.FlightPathState.Reachable
        or not Positive(offer.slotIndex)
        or offer.slotIndex ~= node.slotIndex
    then
        return nil
    end
    local price = TaxiNodeCost and TaxiNodeCost(offer.slotIndex)
    if not Price(price) then return nil end
    return {
        fromNodeID = self.currentNodeID,
        toNodeID = nodeID,
        priceCopper = price,
        slotIndex = offer.slotIndex,
        signature = offer.signature,
    }
end--[[APR_DIAG]]; taxi.GetQuote = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:250:taxi:GetQuote#20", taxi.GetQuote)--[[/APR_DIAG]]

function taxi:GetMeasuredDuration(from, to, signature)
    local data = self:GetCharacterData()
    local record = data and data.durations[signature or (tostring(from) .. ">" .. tostring(to))]
    return type(record) == "table" and Positive(record.seconds) and record.seconds or nil
end--[[APR_DIAG]]; taxi.GetMeasuredDuration = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:279:taxi:GetMeasuredDuration#21", taxi.GetMeasuredDuration)--[[/APR_DIAG]]

local function Available(api, nodeID)
    return APR.HasTaxiNode
        and APR:HasTaxiNode(nodeID) == true
        and (not api.IsNodeAvailable or api.IsNodeAvailable(nodeID) == true)
end--[[APR_DIAG]]; Available = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:285:Available#22", Available)--[[/APR_DIAG]]

-- A probe cannot beat a route shorter than the boarding time alone.
function taxi:CanProbeBeat(baselineSeconds)
    return not Number(baselineSeconds) or baselineSeconds > Constants.BOARDING_SECONDS
end--[[APR_DIAG]]; taxi.CanProbeBeat = APRTrace("APR-Core/features/navigation/NavigationTaxi.lua:292:taxi:CanProbeBeat#23", taxi.CanProbeBeat)--[[/APR_DIAG]]

